<?php declare(strict_types=1);require_once __DIR__.'/../../bootstrap/app.php';use App\Services\Auth;use App\Services\DispatchService;Auth::requirePermission('SHIPMENT_VIEW_SHIPPER');$c=Auth::context()['companies'][0]??null;if(!$c){http_response_code(403);exit('Company required');}$rows=DispatchService::shipperTrips((int)$c['company_id']);$pageTitle='Shipment Progress';require BASE_PATH.'/app/Views/layout/header.php';?><h1>Shipment progress</h1><div class="card table-wrap"><table><thead><tr><th>Load</th><th>Shipment</th><th>Route</th><th>Truck</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as$r):?><tr><td><?=h($r['load_ref'])?></td><td><?=h($r['shipment_ref'])?></td><td><?=h($r['origin_city'].' → '.$r['destination_city'])?></td><td><?=h($r['registration_number'])?></td><td><span class="status-pill status-<?=h($r['shipment_status'])?>"><?=h(str_replace('_',' ',$r['shipment_status']))?></span></td><td><a href="<?=h(\App\Support\Url::to('tracking/view.php?id='.$r['trip_id']))?>">Track</a></td></tr><?php endforeach;?></tbody></table></div><?php require BASE_PATH.'/app/Views/layout/footer.php';
